import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.CXsxtpvq.js";const o="/asset-studio/shots/en/01-prompts-empty.webp",n="/asset-studio/shots/en/02-sample-imported.webp",u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),i={name:"guide/getting-started.md"};function d(l,t,h,p,g,m){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Asset Studio is a web app that works on top of <a href="https://github.com/comfyanonymous/ComfyUI" target="_blank" rel="noreferrer">ComfyUI</a> on your own PC. You keep a character&#39;s appearance, outfits and expressions as prompt pieces, generate every combination you need in one batch, review the results, and train a LoRA for that character from the images you approved.</p><p>This guide walks through the screens once Asset Studio is installed. For installation and the models and nodes you need, see the <a href="https://github.com/kiritype/asset-studio#readme" target="_blank" rel="noreferrer">README</a>.</p><h2 id="the-overall-flow" tabindex="-1">The overall flow <a class="header-anchor" href="#the-overall-flow" aria-label="Permalink to &quot;The overall flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Prompt library → generate images → review in the gallery → train a LoRA → generate again with it</span></span>
<span class="line"><span>                                     ↘ image tools (tags, inpaint, background removal, censor)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Menu</th><th>What it does</th></tr></thead><tbody><tr><td>Prompts</td><td>Create and edit prompt pieces: works, characters, outfits, expressions and more.</td></tr><tr><td>Jobs</td><td>Pick characters × outfits × expressions × count and queue them.</td></tr><tr><td>Lab</td><td>Try one prompt with several seeds or setting values and compare.</td></tr><tr><td>Image tools</td><td>Read metadata, tag, inpaint, remove backgrounds, censor, convert to WebP.</td></tr><tr><td>LoRA</td><td>Build a dataset from passed images, train, and register the result.</td></tr><tr><td>Gallery</td><td>Browse generated images and review them as pass or fail.</td></tr><tr><td>Settings</td><td>Language and theme, ComfyUI connection, LoRA training, GPU rules.</td></tr></tbody></table><p>The ComfyUI connection and the queue button are always at the top right.</p><h2 id="starting" tabindex="-1">Starting <a class="header-anchor" href="#starting" aria-label="Permalink to &quot;Starting&quot;">​</a></h2><p>Run <code>launch.bat</code>; your browser opens <a href="http://127.0.0.1:8195" target="_blank" rel="noreferrer">http://127.0.0.1:8195</a>. ComfyUI must be running for generation and the image tools (default address <a href="http://127.0.0.1:8188" target="_blank" rel="noreferrer">http://127.0.0.1:8188</a>).</p><p>On the first start the library is empty.</p><p><img src="`+o+'" alt="Empty prompt library"></p><h2 id="start-with-the-sample-work" tabindex="-1">Start with the sample work <a class="header-anchor" href="#start-with-the-sample-work" aria-label="Permalink to &quot;Start with the sample work&quot;">​</a></h2><p>Press <strong>Import sample</strong> at the top right of <strong>Prompts</strong> to create the sample work &quot;Starlight Academy&quot;. It has two students (Lyra Vance and Kai Rowan), a school uniform and a mage robe, five expressions and two compositions, so you can generate right away.</p><p><img src="'+n+'" alt="Sample imported"></p><p>The sample has no generation settings (model, sampler). Choose a model under <strong>Generation settings</strong> the first time you <a href="./generate">generate</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Look at how the sample is built in the <a href="./library">prompt library</a>.</li><li><a href="./generate">Generate</a> Lyra&#39;s five expressions.</li><li>Pass the images you like in the <a href="./gallery">gallery</a>.</li><li>Train Lyra&#39;s LoRA from the passed images in <a href="./lora">LoRA training</a>.</li></ol>',17)])])}const f=e(i,[["render",d]]);export{u as __pageData,f as default};
